import base64
import hashlib
import json
import os
import pathlib
import plistlib
import subprocess
import time
import uuid


NATIVE_SWIFT_SOURCE = "import AppKit
import UniformTypeIdentifiers
import Vision

enum AppLanguage {
    static let isEnglish = ProcessInfo.processInfo.environment["NOTCH_LOCALE"]?.lowercased().hasPrefix("en") == true
}

func localized(_ zhHans: String, _ english: String) -> String {
    AppLanguage.isEnglish ? english : zhHans
}

enum Tool: String, CaseIterable {
    case select, pen, arrow, rect, ellipse, text, bubble, watermark, number
    case highlight, spotlight, magnify, mosaic, blur, redact

    var title: String {
        switch self {
        case .select: return localized("选择", "Select")
        case .pen: return localized("画笔", "Pen")
        case .arrow: return localized("箭头", "Arrow")
        case .rect: return localized("矩形", "Rectangle")
        case .ellipse: return localized("椭圆", "Ellipse")
        case .text: return localized("文字", "Text")
        case .bubble: return localized("对话气泡", "Speech Bubble")
        case .watermark: return localized("水印", "Watermark")
        case .number: return localized("步骤编号", "Step Number")
        case .highlight: return localized("高亮", "Highlight")
        case .spotlight: return localized("聚光", "Spotlight")
        case .magnify: return localized("圈选放大", "Magnify")
        case .mosaic: return localized("马赛克", "Mosaic")
        case .blur: return localized("强模糊", "Strong Blur")
        case .redact: return localized("纯色遮盖", "Redact")
        }
    }

    var symbol: String {
        switch self {
        case .select: return "cursorarrow"
        case .pen: return "pencil.tip"
        case .arrow: return "arrow.up.right"
        case .rect: return "rectangle"
        case .ellipse: return "circle"
        case .text: return "textformat"
        case .bubble: return "bubble.left"
        case .watermark: return "signature"
        case .number: return "1.circle"
        case .highlight: return "highlighter"
        case .spotlight: return "flashlight.on.fill"
        case .magnify: return "plus.magnifyingglass"
        case .mosaic: return "square.grid.3x3.square"
        case .blur: return "drop.halffull"
        case .redact: return "rectangle.fill"
        }
    }
}

enum FrameStyle: Int, CaseIterable {
    case none, thin, dark, paper, window, browser, shadow, film

    var title: String {
        switch self {
        case .none: return localized("无边框", "No Frame")
        case .thin: return localized("细白边", "Thin White")
        case .dark: return localized("深色画框", "Dark Frame")
        case .paper: return localized("留白相纸", "Photo Print")
        case .window: return localized("macOS 窗口", "macOS Window")
        case .browser: return localized("浏览器窗口", "Browser Window")
        case .shadow: return localized("悬浮阴影", "Floating Shadow")
        case .film: return localized("胶片边框", "Film Frame")
        }
    }
}

enum BubbleStyle: Int, CaseIterable {
    case classic, capsule, cloud, burst, thought

    var title: String {
        switch self {
        case .classic: return localized("经典气泡", "Classic")
        case .capsule: return localized("圆润气泡", "Capsule")
        case .cloud: return localized("云朵气泡", "Cloud")
        case .burst: return localized("强调爆炸", "Burst")
        case .thought: return localized("思考气泡", "Thought")
        }
    }
}

final class Annotation: NSObject {
    let type: Tool
    var rect: CGRect = .zero
    var start: CGPoint = .zero
    var end: CGPoint = .zero
    var points: [CGPoint] = []
    var text = ""
    var color = NSColor.systemRed
    var lineWidth: CGFloat = 6
    var fontSize: CGFloat = 36
    var backgroundEnabled = true
    var backgroundColor = NSColor.black.withAlphaComponent(0.72)
    var bubbleStyle: BubbleStyle = .classic
    var opacity: CGFloat = 0.24
    var rotation: CGFloat = -24
    var number = 1
    var stickerIndex = 0
    var effectImage: NSImage?

    init(type: Tool) {
        self.type = type
    }

    func clone() -> Annotation {
        let item = Annotation(type: type)
        item.rect = rect
        item.start = start
        item.end = end
        item.points = points
        item.text = text
        item.color = color
        item.lineWidth = lineWidth
        item.fontSize = fontSize
        item.backgroundEnabled = backgroundEnabled
        item.backgroundColor = backgroundColor
        item.bubbleStyle = bubbleStyle
        item.opacity = opacity
        item.rotation = rotation
        item.number = number
        item.stickerIndex = stickerIndex
        item.effectImage = effectImage
        return item
    }

    func bounds() -> CGRect {
        switch type {
        case .pen:
            guard let first = points.first else { return .zero }
            var box = CGRect(origin: first, size: .zero)
            for point in points.dropFirst() { box = box.union(CGRect(origin: point, size: .zero)) }
            return box.insetBy(dx: -lineWidth, dy: -lineWidth)
        case .arrow:
            return CGRect(
                x: min(start.x, end.x), y: min(start.y, end.y),
                width: abs(end.x - start.x), height: abs(end.y - start.y)
            ).insetBy(dx: -lineWidth * 2, dy: -lineWidth * 2)
        case .number:
            let radius = max(18, lineWidth * 3)
            return CGRect(x: start.x - radius, y: start.y - radius, width: radius * 2, height: radius * 2)
        case .text:
            let font = NSFont.systemFont(ofSize: fontSize, weight: .semibold)
            let size = (text as NSString).size(withAttributes: [.font: font])
            return CGRect(x: rect.minX, y: rect.minY, width: size.width + 16, height: max(size.height + 10, fontSize * 1.3))
        case .bubble:
            return rect.standardized.insetBy(dx: -10, dy: -20)
        case .watermark:
            let box = rect.standardized
            let radians = abs(rotation * .pi / 180)
            let width = abs(box.width * cos(radians)) + abs(box.height * sin(radians))
            let height = abs(box.width * sin(radians)) + abs(box.height * cos(radians))
            return CGRect(x: box.midX - width / 2, y: box.midY - height / 2, width: width, height: height)
        case .magnify:
            let lens = magnifierRect()
            return rect.union(lens)
        default:
            return rect.standardized
        }
    }

    func magnifierRect() -> CGRect {
        let size = min(300, max(140, max(rect.width, rect.height) * 1.35))
        return CGRect(x: rect.maxX + 28, y: rect.midY - size / 2, width: size, height: size)
    }
}

struct EditorSnapshot {
    let annotations: [Annotation]
    let frameStyle: FrameStyle
    let nextNumber: Int
}

struct FrameLayout {
    let origin: CGPoint
    let size: CGSize
}

final class CanvasView: NSView {
    weak var editor: EditorViewController?
    let baseImage: NSImage
    let stickerImages: [NSImage]
    var annotations: [Annotation] = []
    var selectedIndex: Int?
    var currentTool: Tool = .select
    var currentColor = NSColor.systemRed
    var currentLineWidth: CGFloat = 6
    var currentFontSize: CGFloat = 36
    var currentTextBackgroundEnabled = true
    var currentTextBackgroundColor = NSColor.black.withAlphaComponent(0.72)
    var currentBubbleStyle: BubbleStyle = .classic
    var currentWatermarkOpacity: CGFloat = 0.24
    var currentWatermarkAngle: CGFloat = -24
    var frameStyle: FrameStyle = .paper
    var zoom: CGFloat = 1
    var nextNumber = 1

    private var history: [EditorSnapshot] = []
    private var historyIndex = -1
    private var gestureStart: CGPoint?
    private var originalAnnotation: Annotation?
    private var resizing = false
    private var drawingIndex: Int?

    override var isFlipped: Bool { true }
    override var acceptsFirstResponder: Bool { true }

    init(image: NSImage, stickers: [NSImage]) {
        baseImage = image
        stickerImages = stickers
        super.init(frame: .zero)
        wantsLayer = true
        layer?.shadowColor = NSColor.black.cgColor
        layer?.shadowOpacity = 0.42
        layer?.shadowRadius = 22
        layer?.shadowOffset = CGSize(width: 0, height: -10)
        updateGeometry()
        recordHistory()
    }

    required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }

    var imageSize: CGSize { baseImage.size }

    func frameLayout() -> FrameLayout {
        switch frameStyle {
        case .none: return FrameLayout(origin: .zero, size: imageSize)
        case .thin: return FrameLayout(origin: CGPoint(x: 14, y: 14), size: CGSize(width: imageSize.width + 28, height: imageSize.height + 28))
        case .dark: return FrameLayout(origin: CGPoint(x: 26, y: 26), size: CGSize(width: imageSize.width + 52, height: imageSize.height + 52))
        case .paper: return FrameLayout(origin: CGPoint(x: 52, y: 52), size: CGSize(width: imageSize.width + 104, height: imageSize.height + 122))
        case .window: return FrameLayout(origin: CGPoint(x: 18, y: 46), size: CGSize(width: imageSize.width + 36, height: imageSize.height + 64))
        case .browser: return FrameLayout(origin: CGPoint(x: 18, y: 58), size: CGSize(width: imageSize.width + 36, height: imageSize.height + 76))
        case .shadow: return FrameLayout(origin: CGPoint(x: 42, y: 42), size: CGSize(width: imageSize.width + 84, height: imageSize.height + 84))
        case .film: return FrameLayout(origin: CGPoint(x: 42, y: 28), size: CGSize(width: imageSize.width + 84, height: imageSize.height + 56))
        }
    }

    func updateGeometry() {
        let output = frameLayout().size
        bounds = CGRect(origin: .zero, size: output)
        frame.size = CGSize(width: output.width * zoom, height: output.height * zoom)
        needsDisplay = true
    }

    func setZoom(_ value: CGFloat) {
        zoom = min(2.0, max(0.15, value))
        updateGeometry()
        editor?.updateZoomLabel()
    }

    func fit(in size: CGSize) {
        let output = frameLayout().size
        setZoom(min(1, max(0.15, min((size.width - 80) / output.width, (size.height - 80) / output.height))))
    }

    override func draw(_ dirtyRect: NSRect) {
        super.draw(dirtyRect)
        drawScene(includeSelection: true)
    }

    private func drawScene(includeSelection: Bool) {
        guard let context = NSGraphicsContext.current else { return }
        let layout = frameLayout()
        drawFrame(layout: layout)
        context.saveGraphicsState()
        context.cgContext.translateBy(x: layout.origin.x, y: layout.origin.y)
        for annotation in annotations where !drawStickerIfNeeded(annotation) { draw(annotation) }
        if includeSelection, let index = selectedIndex, annotations.indices.contains(index) {
            drawSelection(for: annotations[index])
        }
        context.restoreGraphicsState()
    }

    private func roundedPath(_ rect: CGRect, radius: CGFloat) -> NSBezierPath {
        NSBezierPath(roundedRect: rect, xRadius: radius, yRadius: radius)
    }

    private func drawFrame(layout: FrameLayout) {
        let full = CGRect(origin: .zero, size: layout.size)
        switch frameStyle {
        case .none:
            break
        case .thin:
            NSColor.white.setFill(); full.fill()
        case .dark:
            NSColor(calibratedWhite: 0.075, alpha: 1).setFill(); roundedPath(full, radius: 12).fill()
        case .paper:
            NSColor(calibratedRed: 0.965, green: 0.945, blue: 0.89, alpha: 1).setFill(); full.fill()
            NSGraphicsContext.saveGraphicsState()
            let shadow = NSShadow(); shadow.shadowColor = NSColor.black.withAlphaComponent(0.28); shadow.shadowBlurRadius = 18; shadow.shadowOffset = CGSize(width: 0, height: -8); shadow.set()
            NSColor.white.setFill()
            CGRect(x: layout.origin.x - 12, y: layout.origin.y - 12, width: imageSize.width + 24, height: imageSize.height + 24).fill()
            NSGraphicsContext.restoreGraphicsState()
        case .window:
            NSColor(calibratedWhite: 0.93, alpha: 1).setFill(); roundedPath(full, radius: 12).fill()
            for (index, color) in [NSColor.systemRed, .systemYellow, .systemGreen].enumerated() {
                color.setFill(); NSBezierPath(ovalIn: CGRect(x: 16 + CGFloat(index) * 20, y: 15, width: 12, height: 12)).fill()
            }
        case .browser:
            NSColor(calibratedWhite: 0.9, alpha: 1).setFill(); roundedPath(full, radius: 12).fill()
            for (index, color) in [NSColor.systemRed, .systemYellow, .systemGreen].enumerated() {
                color.setFill(); NSBezierPath(ovalIn: CGRect(x: 15 + CGFloat(index) * 18, y: 14, width: 11, height: 11)).fill()
            }
            NSColor.white.withAlphaComponent(0.88).setFill()
            roundedPath(CGRect(x: 82, y: 10, width: max(120, full.width - 104), height: 25), radius: 7).fill()
        case .shadow:
            NSGraphicsContext.saveGraphicsState()
            let shadow = NSShadow(); shadow.shadowColor = NSColor.black.withAlphaComponent(0.42); shadow.shadowBlurRadius = 26; shadow.shadowOffset = CGSize(width: 0, height: -10); shadow.set()
            NSColor.white.setFill(); CGRect(origin: layout.origin, size: imageSize).fill()
            NSGraphicsContext.restoreGraphicsState()
        case .film:
            NSColor(calibratedWhite: 0.055, alpha: 1).setFill(); full.fill()
            NSColor(calibratedWhite: 0.85, alpha: 1).setFill()
            var x: CGFloat = 16
            while x < full.width - 16 {
                roundedPath(CGRect(x: x, y: 8, width: 18, height: 10), radius: 2).fill()
                roundedPath(CGRect(x: x, y: full.height - 18, width: 18, height: 10), radius: 2).fill()
                x += 32
            }
        }
        baseImage.draw(in: CGRect(origin: layout.origin, size: imageSize), from: .zero, operation: .sourceOver, fraction: 1, respectFlipped: true, hints: [.interpolation: NSImageInterpolation.high])
        if frameStyle == .thin {
            NSColor(calibratedWhite: 0.78, alpha: 1).setStroke()
            NSBezierPath(rect: CGRect(origin: layout.origin, size: imageSize).insetBy(dx: -0.5, dy: -0.5)).stroke()
        }
    }

    private func draw(_ item: Annotation) {
        NSGraphicsContext.saveGraphicsState()
        item.color.setStroke(); item.color.setFill()
        let path = NSBezierPath(); path.lineWidth = item.lineWidth; path.lineCapStyle = .round; path.lineJoinStyle = .round
        switch item.type {
        case .pen:
            guard let first = item.points.first else { break }
            path.move(to: first)
            for point in item.points.dropFirst() { path.line(to: point) }
            path.stroke()
        case .arrow:
            path.move(to: item.start); path.line(to: item.end); path.stroke()
            let angle = atan2(item.end.y - item.start.y, item.end.x - item.start.x)
            let head = max(16, item.lineWidth * 3.4)
            let arrow = NSBezierPath(); arrow.move(to: item.end)
            arrow.line(to: CGPoint(x: item.end.x - head * cos(angle - .pi / 6), y: item.end.y - head * sin(angle - .pi / 6)))
            arrow.line(to: CGPoint(x: item.end.x - head * 0.72 * cos(angle), y: item.end.y - head * 0.72 * sin(angle)))
            arrow.line(to: CGPoint(x: item.end.x - head * cos(angle + .pi / 6), y: item.end.y - head * sin(angle + .pi / 6)))
            arrow.close(); arrow.fill()
        case .rect:
            path.appendRect(item.rect.standardized); path.stroke()
        case .ellipse:
            path.appendOval(in: item.rect.standardized); path.stroke()
        case .highlight:
            item.color.withAlphaComponent(0.3).setFill(); roundedPath(item.rect.standardized, radius: 7).fill()
        case .spotlight:
            guard let context = NSGraphicsContext.current?.cgContext else { break }
            context.saveGState(); context.beginTransparencyLayer(auxiliaryInfo: nil)
            NSColor.black.withAlphaComponent(0.66).setFill(); CGRect(origin: .zero, size: imageSize).fill()
            context.setBlendMode(.destinationOut); NSColor.black.setFill(); NSBezierPath(ovalIn: item.rect.standardized).fill()
            context.endTransparencyLayer(); context.restoreGState()
        case .mosaic, .blur:
            if let effect = item.effectImage {
                NSGraphicsContext.current?.imageInterpolation = item.type == .mosaic ? .none : .high
                effect.draw(in: item.rect.standardized, from: .zero, operation: .sourceOver, fraction: 1, respectFlipped: true, hints: nil)
                if item.type == .blur { NSColor(calibratedWhite: 0.42, alpha: 0.2).setFill(); item.rect.standardized.fill() }
            }
        case .redact:
            roundedPath(item.rect.standardized, radius: min(5, item.rect.height / 4)).fill()
        case .text:
            let font = NSFont.systemFont(ofSize: item.fontSize, weight: .semibold)
            let box = item.bounds()
            if item.backgroundEnabled {
                item.backgroundColor.setFill(); roundedPath(box.insetBy(dx: -5, dy: -3), radius: 7).fill()
            }
            (item.text as NSString).draw(at: CGPoint(x: item.rect.minX + 4, y: item.rect.minY + 3), withAttributes: [.font: font, .foregroundColor: item.color])
        case .bubble:
            drawBubble(item)
        case .watermark:
            drawWatermark(item)
        case .number:
            let radius = max(18, item.lineWidth * 3); NSBezierPath(ovalIn: CGRect(x: item.start.x - radius, y: item.start.y - radius, width: radius * 2, height: radius * 2)).fill()
            let text = "\(item.number)" as NSString; let font = NSFont.systemFont(ofSize: radius * 1.08, weight: .bold); let size = text.size(withAttributes: [.font: font])
            text.draw(at: CGPoint(x: item.start.x - size.width / 2, y: item.start.y - size.height / 2 - 1), withAttributes: [.font: font, .foregroundColor: NSColor.white])
        case .magnify:
            let source = item.rect.standardized; let lens = constrainedLens(item.magnifierRect())
            item.color.setStroke(); let sourcePath = NSBezierPath(rect: source); sourcePath.lineWidth = max(2, item.lineWidth / 2); sourcePath.setLineDash([8, 6], count: 2, phase: 0); sourcePath.stroke()
            let connector = NSBezierPath(); connector.move(to: CGPoint(x: source.midX, y: source.midY)); connector.line(to: CGPoint(x: lens.midX, y: lens.midY)); connector.lineWidth = max(2, item.lineWidth / 2); connector.stroke()
            NSGraphicsContext.saveGraphicsState(); NSBezierPath(ovalIn: lens).addClip(); baseImage.draw(in: lens, from: source, operation: .sourceOver, fraction: 1, respectFlipped: true, hints: [.interpolation: NSImageInterpolation.high]); NSGraphicsContext.restoreGraphicsState()
            NSColor.white.setStroke(); let outer = NSBezierPath(ovalIn: lens); outer.lineWidth = max(8, item.lineWidth + 5); outer.stroke(); item.color.setStroke(); outer.lineWidth = max(3, item.lineWidth); outer.stroke()
        case .select:
            break
        }
        NSGraphicsContext.restoreGraphicsState()
    }

    private func drawBubble(_ item: Annotation) {
        let box = item.rect.standardized
        let strokeWidth = max(2, item.lineWidth / 2)
        let body = bubbleBodyPath(for: item.bubbleStyle, rect: box)
        NSColor.white.setFill(); item.color.setStroke(); body.lineWidth = strokeWidth; body.fill(); body.stroke()

        if item.bubbleStyle == .classic || item.bubbleStyle == .capsule {
            let tail = NSBezierPath()
            if item.bubbleStyle == .classic {
                tail.move(to: CGPoint(x: box.minX + 28, y: box.maxY - 1))
                tail.line(to: CGPoint(x: box.minX + 16, y: box.maxY + 20))
                tail.line(to: CGPoint(x: box.minX + 56, y: box.maxY - 1))
            } else {
                tail.move(to: CGPoint(x: box.maxX - 62, y: box.maxY - 2))
                tail.line(to: CGPoint(x: box.maxX - 20, y: box.maxY + 18))
                tail.line(to: CGPoint(x: box.maxX - 30, y: box.maxY - 2))
            }
            tail.close(); NSColor.white.setFill(); item.color.setStroke(); tail.lineWidth = strokeWidth; tail.fill(); tail.stroke()
        } else if item.bubbleStyle == .thought {
            let first = NSBezierPath(ovalIn: CGRect(x: box.minX + 18, y: box.maxY + 7, width: 16, height: 16))
            let second = NSBezierPath(ovalIn: CGRect(x: box.minX + 4, y: box.maxY + 25, width: 10, height: 10))
            for dot in [first, second] { NSColor.white.setFill(); item.color.setStroke(); dot.lineWidth = strokeWidth; dot.fill(); dot.stroke() }
        }

        let textRect: CGRect
        switch item.bubbleStyle {
        case .burst: textRect = box.insetBy(dx: 28, dy: 22)
        case .cloud, .thought: textRect = box.insetBy(dx: 24, dy: 18)
        default: textRect = box.insetBy(dx: 14, dy: 12)
        }
        let font = NSFont.systemFont(ofSize: max(16, item.fontSize * 0.72), weight: .semibold)
        let paragraph = NSMutableParagraphStyle(); paragraph.alignment = .center; paragraph.lineBreakMode = .byWordWrapping
        let attributes: [NSAttributedString.Key: Any] = [
            .font: font,
            .foregroundColor: NSColor(calibratedWhite: 0.08, alpha: 1),
            .paragraphStyle: paragraph,
        ]
        let measured = (item.text as NSString).boundingRect(with: textRect.size, options: [.usesLineFragmentOrigin, .usesFontLeading], attributes: attributes)
        let height = min(textRect.height, ceil(measured.height))
        let centered = CGRect(x: textRect.minX, y: textRect.midY - height / 2, width: textRect.width, height: height)
        (item.text as NSString).draw(in: centered, withAttributes: attributes)
    }

    private func bubbleBodyPath(for style: BubbleStyle, rect: CGRect) -> NSBezierPath {
        switch style {
        case .classic:
            return roundedPath(rect, radius: 14)
        case .capsule:
            return roundedPath(rect, radius: min(rect.height / 2, 32))
        case .thought:
            return NSBezierPath(ovalIn: rect)
        case .burst:
            let path = NSBezierPath(); let points = 20
            for index in 0..<points {
                let angle = CGFloat(index) / CGFloat(points) * .pi * 2 - .pi / 2
                let radius = index.isMultiple(of: 2) ? CGFloat(1) : CGFloat(0.78)
                let point = CGPoint(x: rect.midX + cos(angle) * rect.width * 0.5 * radius, y: rect.midY + sin(angle) * rect.height * 0.5 * radius)
                index == 0 ? path.move(to: point) : path.line(to: point)
            }
            path.close(); return path
        case .cloud:
            let path = NSBezierPath()
            path.move(to: CGPoint(x: rect.minX + rect.width * 0.16, y: rect.maxY - rect.height * 0.12))
            path.curve(to: CGPoint(x: rect.minX + rect.width * 0.13, y: rect.minY + rect.height * 0.48), controlPoint1: CGPoint(x: rect.minX - rect.width * 0.02, y: rect.maxY - rect.height * 0.18), controlPoint2: CGPoint(x: rect.minX - rect.width * 0.02, y: rect.minY + rect.height * 0.58))
            path.curve(to: CGPoint(x: rect.minX + rect.width * 0.43, y: rect.minY + rect.height * 0.18), controlPoint1: CGPoint(x: rect.minX + rect.width * 0.12, y: rect.minY + rect.height * 0.24), controlPoint2: CGPoint(x: rect.minX + rect.width * 0.28, y: rect.minY + rect.height * 0.08))
            path.curve(to: CGPoint(x: rect.minX + rect.width * 0.78, y: rect.minY + rect.height * 0.32), controlPoint1: CGPoint(x: rect.minX + rect.width * 0.55, y: rect.minY - rect.height * 0.02), controlPoint2: CGPoint(x: rect.minX + rect.width * 0.76, y: rect.minY + rect.height * 0.08))
            path.curve(to: CGPoint(x: rect.maxX - rect.width * 0.08, y: rect.maxY - rect.height * 0.24), controlPoint1: CGPoint(x: rect.maxX + rect.width * 0.02, y: rect.minY + rect.height * 0.31), controlPoint2: CGPoint(x: rect.maxX + rect.width * 0.04, y: rect.maxY - rect.height * 0.40))
            path.curve(to: CGPoint(x: rect.minX + rect.width * 0.58, y: rect.maxY - rect.height * 0.08), controlPoint1: CGPoint(x: rect.maxX - rect.width * 0.04, y: rect.maxY), controlPoint2: CGPoint(x: rect.minX + rect.width * 0.76, y: rect.maxY + rect.height * 0.02))
            path.curve(to: CGPoint(x: rect.minX + rect.width * 0.16, y: rect.maxY - rect.height * 0.12), controlPoint1: CGPoint(x: rect.minX + rect.width * 0.42, y: rect.maxY + rect.height * 0.06), controlPoint2: CGPoint(x: rect.minX + rect.width * 0.25, y: rect.maxY + rect.height * 0.02))
            path.close(); return path
        }
    }

    private func drawWatermark(_ item: Annotation) {
        guard let context = NSGraphicsContext.current?.cgContext else { return }
        let box = item.rect.standardized
        context.saveGState(); context.translateBy(x: box.midX, y: box.midY); context.rotate(by: item.rotation * .pi / 180)
