    private func constrainedLens(_ proposed: CGRect) -> CGRect {
        var lens = proposed
        if lens.maxX > imageSize.width { lens.origin.x = max(8, proposed.minX - proposed.width - 56) }
        lens.origin.y = max(8, min(imageSize.height - lens.height - 8, lens.origin.y))
