    }

    private func drawSelection(for item: Annotation) {
        let box = item.bounds().insetBy(dx: -5, dy: -5)
        NSColor.systemBlue.setStroke(); let path = NSBezierPath(rect: box); path.lineWidth = 2; path.setLineDash([7, 5], count: 2, phase: 0); path.stroke()
        NSColor.white.setFill(); NSColor.systemBlue.setStroke(); let handle = CGRect(x: box.maxX - 5, y: box.maxY - 5, width: 11, height: 11); handle.fill(); NSBezierPath(rect: handle).stroke()
