    private func localPoint(from event: NSEvent) -> CGPoint {
        let point = convert(event.locationInWindow, from: nil)
        let origin = frameLayout().origin
        return CGPoint(x: point.x - origin.x, y: point.y - origin.y)
    }

    private func isInsideImage(_ point: CGPoint) -> Bool {
        CGRect(origin: .zero, size: imageSize).contains(point)
    }

    private func hitTestAnnotation(_ point: CGPoint) -> Int? {
        for index in annotations.indices.reversed() where annotations[index].bounds().insetBy(dx: -10, dy: -10).contains(point) { return index }
        return nil
    }

    private func onResizeHandle(_ point: CGPoint) -> Bool {
        guard let index = selectedIndex else { return false }
        let box = annotations[index].bounds()
        return hypot(point.x - box.maxX, point.y - box.maxY) < 18 / max(zoom, 0.3)
    }

    override func mouseDown(with event: NSEvent) {
        window?.makeFirstResponder(self)
        let point = localPoint(from: event)
        guard isInsideImage(point) else { return }
        if currentTool == .text || currentTool == .bubble || currentTool == .watermark {
            let existing = event.clickCount > 1 ? hitTestAnnotation(point) : nil
            promptForText(at: point, existingIndex: existing)
            return
        }
        if currentTool == .number {
            let item = Annotation(type: .number); item.start = point; applyStyle(to: item); item.number = nextNumber; nextNumber += 1
            annotations.append(item); selectedIndex = annotations.count - 1; recordHistory(); needsDisplay = true; return
        }
        if currentTool == .select {
            if event.clickCount > 1, let index = hitTestAnnotation(point), annotations[index].type == .text || annotations[index].type == .bubble || annotations[index].type == .watermark {
                selectedIndex = index; promptForText(at: point, existingIndex: index); return
            }
            resizing = onResizeHandle(point)
            if !resizing { selectedIndex = hitTestAnnotation(point) }
            if let index = selectedIndex { originalAnnotation = annotations[index].clone(); gestureStart = point }
            needsDisplay = true; editor?.selectionDidChange(); return
        }
        let item = Annotation(type: currentTool); applyStyle(to: item); item.start = point; item.end = point; item.rect = CGRect(origin: point, size: .zero)
        if currentTool == .pen { item.points = [point] }
        annotations.append(item); drawingIndex = annotations.count - 1; selectedIndex = drawingIndex; gestureStart = point; needsDisplay = true
    }

    override func mouseDragged(with event: NSEvent) {
        let point = localPoint(from: event)
        if currentTool == .select, let start = gestureStart, let index = selectedIndex, let original = originalAnnotation {
            annotations[index] = original.clone()
            if resizing { resize(annotations[index], from: original.bounds(), to: point) }
            else { translate(annotations[index], by: CGPoint(x: point.x - start.x, y: point.y - start.y)) }
            needsDisplay = true; return
        }
        guard let index = drawingIndex, let start = gestureStart else { return }
        let item = annotations[index]
        if item.type == .pen { item.points.append(point) }
        else if item.type == .arrow { item.end = point }
        else { item.rect = CGRect(x: min(start.x, point.x), y: min(start.y, point.y), width: abs(point.x - start.x), height: abs(point.y - start.y)) }
        needsDisplay = true
    }

    override func mouseUp(with event: NSEvent) {
        if currentTool == .select {
            if gestureStart != nil { recordHistory() }
            gestureStart = nil; originalAnnotation = nil; resizing = false; return
        }
        if let index = drawingIndex {
            let item = annotations[index]
            if item.bounds().width < 5 && item.bounds().height < 5 { annotations.remove(at: index); selectedIndex = nil }
            else {
                if item.type == .mosaic { item.effectImage = makeEffectImage(rect: item.rect, step: 12) }
                if item.type == .blur { item.effectImage = makeEffectImage(rect: item.rect, step: max(36, min(72, min(item.rect.width, item.rect.height) * 0.8))) }
                recordHistory()
            }
        }
        drawingIndex = nil; gestureStart = nil; needsDisplay = true
    }

    private func applyStyle(to item: Annotation) {
