    }

    private func promptForText(at point: CGPoint, existingIndex: Int?) {
        let type = existingIndex.flatMap { annotations.indices.contains($0) ? annotations[$0].type : nil } ?? currentTool
        guard type == .text || type == .bubble || type == .watermark else { return }
        let promptTitle: String
        switch type {
        case .text: promptTitle = localized("添加文字", "Add Text")
        case .bubble: promptTitle = localized("添加对话气泡", "Add Speech Bubble")
        default: promptTitle = localized("添加水印", "Add Watermark")
        }
        let alert = NSAlert(); alert.messageText = promptTitle; alert.addButton(withTitle: localized("添加", "Add")); alert.addButton(withTitle: localized("取消", "Cancel"))
        let field = NSTextField(frame: CGRect(x: 0, y: 0, width: 320, height: 28)); field.placeholderString = localized("输入内容", "Enter text")
        if let index = existingIndex { field.stringValue = annotations[index].text }
        alert.accessoryView = field; alert.window.initialFirstResponder = field
        guard alert.runModal() == .alertFirstButtonReturn, !field.stringValue.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        if let index = existingIndex {
            annotations[index].text = field.stringValue; selectedIndex = index
        } else {
            let item = Annotation(type: type); applyStyle(to: item); item.text = field.stringValue
            if type == .text {
                item.rect = CGRect(origin: point, size: CGSize(width: 10, height: currentFontSize * 1.4))
            } else if type == .bubble {
                item.rect = CGRect(x: point.x, y: point.y, width: min(420, max(190, CGFloat(field.stringValue.count) * currentFontSize * 0.55 + 48)), height: max(82, currentFontSize * 2.25))
            } else {
                let width = min(imageSize.width * 0.78, max(260, CGFloat(field.stringValue.count) * currentFontSize * 0.68 + 48))
                let height = max(64, currentFontSize * 1.7)
                item.rect = CGRect(x: max(0, min(imageSize.width - width, point.x - width / 2)), y: max(0, min(imageSize.height - height, point.y - height / 2)), width: width, height: height)
            }
            annotations.append(item); selectedIndex = annotations.count - 1
        }
        recordHistory(); needsDisplay = true; editor?.selectionDidChange()
    }

    private func translate(_ item: Annotation, by delta: CGPoint) {
        item.rect.origin.x += delta.x; item.rect.origin.y += delta.y
        item.start.x += delta.x; item.start.y += delta.y; item.end.x += delta.x; item.end.y += delta.y
        item.points = item.points.map { CGPoint(x: $0.x + delta.x, y: $0.y + delta.y) }
    }

    private func resize(_ item: Annotation, from old: CGRect, to point: CGPoint) {
        let newWidth = max(12, point.x - old.minX), newHeight = max(12, point.y - old.minY)
        let sx = newWidth / max(1, old.width), sy = newHeight / max(1, old.height)
        func mapped(_ value: CGPoint) -> CGPoint { CGPoint(x: old.minX + (value.x - old.minX) * sx, y: old.minY + (value.y - old.minY) * sy) }
        if item.type == .pen { item.points = item.points.map(mapped) }
        else if item.type == .arrow { item.start = mapped(item.start); item.end = mapped(item.end) }
        else if item.type == .number { item.start = mapped(item.start); item.lineWidth *= min(sx, sy) }
        else if item.type == .text || item.type == .watermark { item.rect.origin = mapped(item.rect.origin); item.rect.size = CGSize(width: newWidth, height: newHeight); item.fontSize = max(12, item.fontSize * min(sx, sy)) }
        else { item.rect = CGRect(x: old.minX, y: old.minY, width: newWidth, height: newHeight) }
    }

    private func makeEffectImage(rect: CGRect, step: CGFloat) -> NSImage? {
        let source = rect.standardized.intersection(CGRect(origin: .zero, size: imageSize))
        guard source.width > 1, source.height > 1 else { return nil }
        let tinySize = CGSize(width: max(1, round(source.width / step)), height: max(1, round(source.height / step)))
        let image = NSImage(size: tinySize); image.lockFocusFlipped(true)
        NSGraphicsContext.current?.imageInterpolation = .high
        baseImage.draw(in: CGRect(origin: .zero, size: tinySize), from: source, operation: .copy, fraction: 1, respectFlipped: true, hints: nil)
        image.unlockFocus(); return image
    }

    func addSticker(_ index: Int) {
        guard stickerImages.indices.contains(index) else { return }
        let size: CGFloat = 112; let offset = CGFloat(annotations.filter { $0.type == .select }.count % 5) * 12
        let item = Annotation(type: .select); item.stickerIndex = index; item.rect = CGRect(x: max(0, imageSize.width / 2 - size / 2 + offset), y: max(0, imageSize.height / 2 - size / 2 + offset), width: size, height: size)
