        let coloredText = Annotation(type: .text); applyStyle(to: coloredText); coloredText.text = localized("可选背景颜色", "Custom background color"); coloredText.backgroundColor = NSColor.systemYellow.withAlphaComponent(0.88); coloredText.color = .black; coloredText.fontSize = 28; coloredText.rect = CGRect(x: 430, y: 46, width: 350, height: 54); annotations.append(coloredText)

