            let column = index % 3, row = index / 3
            bubble.rect = CGRect(x: 44 + CGFloat(column) * 300, y: 150 + CGFloat(row) * 150, width: 250, height: 96)
            annotations.append(bubble)
        }

        let watermark = Annotation(type: .watermark); applyStyle(to: watermark); watermark.text = localized("示例水印", "SAMPLE WATERMARK"); watermark.color = .systemRed; watermark.fontSize = 54; watermark.opacity = 0.28; watermark.rotation = -22; watermark.rect = CGRect(x: max(20, imageSize.width / 2 - 280), y: max(20, imageSize.height - 180), width: 560, height: 90); annotations.append(watermark)
        selectedIndex = annotations.count - 1; recordHistory(); needsDisplay = true; editor?.selectionDidChange()
    }

    private func drawStickerIfNeeded(_ item: Annotation) -> Bool {
        guard item.type == .select, stickerImages.indices.contains(item.stickerIndex) else { return false }
        stickerImages[item.stickerIndex].draw(in: item.rect, from: .zero, operation: .sourceOver, fraction: 1, respectFlipped: true, hints: [.interpolation: NSImageInterpolation.high])
        return true
    }

    func changeFrame(_ style: FrameStyle) { frameStyle = style; updateGeometry(); recordHistory() }
    func changeSelectedColor(_ color: NSColor) { currentColor = color; if let index = selectedIndex { annotations[index].color = color; recordHistory(); needsDisplay = true } }
    func changeLineWidth(_ value: CGFloat) { currentLineWidth = value; if let index = selectedIndex { annotations[index].lineWidth = value; recordHistory(); needsDisplay = true } }
    func changeFontSize(_ value: CGFloat) { currentFontSize = value; if let index = selectedIndex, annotations[index].type == .text || annotations[index].type == .bubble || annotations[index].type == .watermark { annotations[index].fontSize = value; recordHistory(); needsDisplay = true } }
    func changeTextBackgroundEnabled(_ enabled: Bool) { currentTextBackgroundEnabled = enabled; if let index = selectedIndex, annotations[index].type == .text { annotations[index].backgroundEnabled = enabled; recordHistory(); needsDisplay = true } }
    func changeTextBackgroundColor(_ color: NSColor) { currentTextBackgroundColor = color; if let index = selectedIndex, annotations[index].type == .text { annotations[index].backgroundColor = color; recordHistory(); needsDisplay = true } }
    func changeBubbleStyle(_ style: BubbleStyle) { currentBubbleStyle = style; if let index = selectedIndex, annotations[index].type == .bubble { annotations[index].bubbleStyle = style; recordHistory(); needsDisplay = true } }
    func changeWatermarkOpacity(_ value: CGFloat) { currentWatermarkOpacity = value; if let index = selectedIndex, annotations[index].type == .watermark { annotations[index].opacity = value; recordHistory(); needsDisplay = true } }
    func changeWatermarkAngle(_ value: CGFloat) { currentWatermarkAngle = value; if let index = selectedIndex, annotations[index].type == .watermark { annotations[index].rotation = value; recordHistory(); needsDisplay = true } }
    var selectedAnnotation: Annotation? { guard let index = selectedIndex, annotations.indices.contains(index) else { return nil }; return annotations[index] }

    override func keyDown(with event: NSEvent) {
        if event.keyCode == 51 || event.keyCode == 117 { deleteSelection() } else { super.keyDown(with: event) }
    }

    func deleteSelection() {
        guard let index = selectedIndex, annotations.indices.contains(index) else { return }
        annotations.remove(at: index); selectedIndex = nil; recordHistory(); needsDisplay = true; editor?.selectionDidChange()
    }

    func undo() { restoreHistory(historyIndex - 1) }
    func redo() { restoreHistory(historyIndex + 1) }
    var canUndo: Bool { historyIndex > 0 }
    var canRedo: Bool { historyIndex >= 0 && historyIndex < history.count - 1 }

    private func recordHistory() {
        let snapshot = EditorSnapshot(annotations: annotations.map { $0.clone() }, frameStyle: frameStyle, nextNumber: nextNumber)
        history = Array(history.prefix(historyIndex + 1)); history.append(snapshot)
        if history.count > 80 { history.removeFirst() }
        historyIndex = history.count - 1; editor?.historyDidChange()
    }

    private func restoreHistory(_ index: Int) {
        guard history.indices.contains(index) else { return }
        let snapshot = history[index]; annotations = snapshot.annotations.map { $0.clone() }; frameStyle = snapshot.frameStyle; nextNumber = snapshot.nextNumber; selectedIndex = nil; historyIndex = index
        updateGeometry(); editor?.syncFrameControl(); editor?.historyDidChange(); editor?.selectionDidChange()
    }

    func renderImage() -> NSImage {
        let output = frameLayout().size
        let image = NSImage(size: output); image.lockFocusFlipped(true); drawScene(includeSelection: false); image.unlockFocus(); return image
    }

    @discardableResult
    func detectSensitive(usingBlur: Bool, showFeedback: Bool = true) -> Int {
        guard let cgImage = baseImage.cgImage(forProposedRect: nil, context: nil, hints: nil) else { return 0 }
        let request = VNRecognizeTextRequest(); request.recognitionLevel = .accurate; request.usesLanguageCorrection = true; request.recognitionLanguages = ["zh-Hans", "en-US"]
        do { try VNImageRequestHandler(cgImage: cgImage, options: [:]).perform([request]) } catch { if showFeedback { editor?.showMessage(localized("文字识别失败", "Text recognition failed")) }; return 0 }
        var matches = 0
        for observation in request.results ?? [] {
            guard let candidate = observation.topCandidates(1).first, isSensitive(candidate.string) else { continue }
            let box = observation.boundingBox
            let rect = CGRect(x: box.minX * imageSize.width - 5, y: (1 - box.maxY) * imageSize.height - 4, width: box.width * imageSize.width + 10, height: box.height * imageSize.height + 8).intersection(CGRect(origin: .zero, size: imageSize))
            let item = Annotation(type: usingBlur ? .blur : .redact); item.rect = rect; item.color = NSColor(calibratedWhite: 0.08, alpha: 1)
            if usingBlur { item.effectImage = makeEffectImage(rect: rect, step: max(36, min(72, min(rect.width, rect.height) * 0.8))) }
            annotations.append(item); matches += 1
        }
        if matches > 0 { selectedIndex = annotations.count - 1; recordHistory(); needsDisplay = true }
        if showFeedback {
            let marked = String(format: localized("已标记 %d 处敏感信息", "Marked %d sensitive items"), matches)
            editor?.showMessage(matches > 0 ? marked : localized("未识别到常见敏感信息", "No common sensitive information found"))
        }
        return matches
    }

    private func isSensitive(_ value: String) -> Bool {
        let compact = value.replacingOccurrences(of: " ", with: "")
        let patterns = ["[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}", "(?:\\+?86[- ]?)?1[3-9]\\d{9}", "\\b\\d{17}[\\dXx]\\b", "(?:\\d[ -]?){13,19}", "(?:token|secret|password|passwd|api[_ -]?key)[:=]?\\S+"]
        return patterns.contains { compact.range(of: $0, options: [.regularExpression, .caseInsensitive]) != nil }
    }

}

final class CenteringClipView: NSClipView {
    override func constrainBoundsRect(_ proposedBounds: NSRect) -> NSRect {
        var bounds = super.constrainBoundsRect(proposedBounds)
        guard let documentView else { return bounds }
        if documentView.frame.width < self.bounds.width { bounds.origin.x = -(self.bounds.width - documentView.frame.width) / 2 }
        if documentView.frame.height < self.bounds.height { bounds.origin.y = -(self.bounds.height - documentView.frame.height) / 2 }
        return bounds
    }
}

