final class ToolButton: NSButton {
    private let glyphView = NSImageView()
    private let nameLabel: NSTextField
    private var glyphLeading: NSLayoutConstraint!
    private var glyphCentered: NSLayoutConstraint!
    private var selected = false

    init(title: String, image: NSImage, target: AnyObject?, action: Selector?) {
        nameLabel = NSTextField(labelWithString: title)
        super.init(frame: .zero)
        self.title = ""
        self.target = target
        self.action = action
        translatesAutoresizingMaskIntoConstraints = false
        isBordered = false
        setButtonType(.momentaryPushIn)
        toolTip = title
        wantsLayer = true
        layer?.cornerRadius = 6
        layer?.borderWidth = 1

        glyphView.translatesAutoresizingMaskIntoConstraints = false
        glyphView.image = image
        glyphView.imageScaling = .scaleProportionallyDown
        glyphView.contentTintColor = .controlAccentColor
        nameLabel.translatesAutoresizingMaskIntoConstraints = false
        nameLabel.font = .systemFont(ofSize: 13, weight: .medium)
        nameLabel.textColor = .labelColor
        nameLabel.lineBreakMode = .byTruncatingTail
        addSubview(glyphView)
        addSubview(nameLabel)

        glyphLeading = glyphView.leadingAnchor.constraint(equalTo: leadingAnchor, constant: 10)
        glyphCentered = glyphView.centerXAnchor.constraint(equalTo: centerXAnchor)
        glyphLeading.isActive = true
        NSLayoutConstraint.activate([
            heightAnchor.constraint(equalToConstant: 34),
            glyphView.centerYAnchor.constraint(equalTo: centerYAnchor),
            glyphView.widthAnchor.constraint(equalToConstant: 22),
            glyphView.heightAnchor.constraint(equalToConstant: 22),
            nameLabel.leadingAnchor.constraint(equalTo: leadingAnchor, constant: 43),
            nameLabel.trailingAnchor.constraint(equalTo: trailingAnchor, constant: -8),
            nameLabel.centerYAnchor.constraint(equalTo: centerYAnchor),
        ])
        updateSelectionAppearance()
    }

    required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }

    override func hitTest(_ point: NSPoint) -> NSView? {
        guard !isHidden, isEnabled, alphaValue > 0, frame.contains(point) else { return nil }
        return self
    }

    func setExpanded(_ value: Bool) {
        nameLabel.isHidden = !value
        glyphLeading.isActive = value
        glyphCentered.isActive = !value
    }

    func setSelected(_ value: Bool) {
        selected = value
        updateSelectionAppearance()
    }

    override func viewDidChangeEffectiveAppearance() {
        super.viewDidChangeEffectiveAppearance()
        updateSelectionAppearance()
    }

    private func updateSelectionAppearance() {
        guard let layer else { return }
        if selected {
            layer.backgroundColor = NSColor.controlAccentColor.withAlphaComponent(0.2).cgColor
            layer.borderColor = NSColor.controlAccentColor.withAlphaComponent(0.9).cgColor
            glyphView.contentTintColor = .controlAccentColor
            nameLabel.textColor = .controlAccentColor
        } else {
            layer.backgroundColor = NSColor.controlBackgroundColor.withAlphaComponent(0.06).cgColor
            layer.borderColor = NSColor.separatorColor.withAlphaComponent(0.2).cgColor
            glyphView.contentTintColor = .secondaryLabelColor
            nameLabel.textColor = .labelColor
        }
    }
}

