    private func effectiveInspectorTool() -> Tool {
        if canvas.currentTool == .select, let item = canvas.selectedAnnotation { return item.type }
        return canvas.currentTool
    }

    private func updateInspectorVisibility() {
        let tool = effectiveInspectorTool()
        inspectorTitle.stringValue = tool.title
        let visible: Set<InspectorSection>
        switch tool {
        case .select:
            visible = [.frames, .stickers]
        case .pen, .arrow, .rect, .ellipse, .number, .magnify:
            visible = [.color, .line]
        case .text:
            visible = [.color, .font, .textBackground]
        case .bubble:
            visible = [.color, .line, .font, .bubble]
        case .watermark:
            visible = [.color, .font, .watermark]
        case .highlight:
            visible = [.color]
        case .redact:
            visible = [.color, .privacy]
        case .blur:
            visible = [.privacy]
        case .spotlight, .mosaic:
            visible = []
        }
        if tool == .blur { privacyMode.selectedSegment = 1 }
        if tool == .redact { privacyMode.selectedSegment = 0 }
        for (section, group) in inspectorSections { group.isHidden = !visible.contains(section) }
        syncInspectorControls()
        inspectorStack.needsLayout = true
    }

