    init(arguments: [String]) { self.arguments = arguments }

    func applicationDidFinishLaunching(_ notification: Notification) { launchEditor() }

    func launchEditor() {
        guard window == nil else { return }
        guard arguments.count >= 3, let image = normalizedImage(path: arguments[1]), let stickers = loadStickers(path: arguments[2]) else { NSApp.terminate(nil); return }
        controller = EditorViewController(image: image, stickers: stickers, sourceName: (arguments[1] as NSString).lastPathComponent)
        window = NSWindow(contentRect: CGRect(x: 0, y: 0, width: 1420, height: 900), styleMask: [.titled, .closable, .miniaturizable, .resizable, .fullSizeContentView], backing: .buffered, defer: false)
