        buildMenus(); NSApp.activate(ignoringOtherApps: true)
        if arguments.contains("--qa-zoomed") { DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) { self.window.zoom(nil) } }
        if arguments.contains("--qa-collapsed") { controller.setSidebarExpanded(false) }
        if let marker = arguments.firstIndex(of: "--qa-sticker"), marker >= 0 { controller.canvas.addSticker(7) }
        if arguments.contains("--qa-privacy") { controller.canvas.detectSensitive(usingBlur: true, showFeedback: false) }
        if arguments.contains("--qa-showcase") { controller.canvas.addQAShowcase() }
        if let marker = arguments.firstIndex(of: "--qa-tool"), arguments.indices.contains(marker + 1) { let tool = arguments[marker + 1]; DispatchQueue.main.asyncAfter(deadline: .now() + 0.25) { self.controller.setToolForQA(tool) } }
        if let marker = arguments.firstIndex(of: "--qa-export"), arguments.indices.contains(marker + 1), let data = pngData(from: controller.canvas.renderImage()) { try? data.write(to: URL(fileURLWithPath: arguments[marker + 1])) }
        DispatchQueue.main.asyncAfter(deadline: .now() + (arguments.contains("--qa-zoomed") ? 0.45 : 0.15)) { self.controller.canvas.fit(in: self.controller.scrollView.contentSize) }
        if let marker = arguments.firstIndex(of: "--snapshot"), arguments.indices.contains(marker + 1) { let path = arguments[marker + 1]; DispatchQueue.main.asyncAfter(deadline: .now() + 1) { self.captureContent(to: path); NSApp.terminate(nil) } }
    }

    func windowWillClose(_ notification: Notification) { NSApp.terminate(nil) }

    private func buildMenus() {
