STICKER_SHEET_BASE64 = ""


def capture_interactive(path):
    result = subprocess.run(
        ["/usr/sbin/screencapture", "-i", "-x", str(path)],
        check=False,
    )
    return result.returncode == 0 and path.exists() and path.stat().st_size > 0


def write_if_changed(path, data):
    if not path.exists() or path.read_bytes() != data:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)


def build_native_editor(cache_dir, sticker_data, locale):
    digest = hashlib.sha256(
        NATIVE_SWIFT_SOURCE.encode("utf-8") + sticker_data + locale.encode("utf-8")
    ).hexdigest()[:16]
    app_dir = cache_dir / f"ScreenshotEditor-{digest}.app"
    contents = app_dir / "Contents"
    executable = contents / "MacOS" / "ScreenshotEditor"
    source_path = cache_dir / f"ScreenshotEditor-{digest}.swift"

    write_if_changed(source_path, NATIVE_SWIFT_SOURCE.encode("utf-8"))
    if not executable.exists():
        executable.parent.mkdir(parents=True, exist_ok=True)
        result = subprocess.run(
            [
                "/usr/bin/swiftc",
                str(source_path),
                "-o",
                str(executable),
                "-framework",
                "AppKit",
                "-framework",
                "Vision",
                "-framework",
                "UniformTypeIdentifiers",
            ],
            check=False,
            capture_output=True,
            text=True,
            timeout=120,
        )
        if result.returncode != 0:
            raise RuntimeError((result.stderr or result.stdout or notch_t("native_compile_failed")).strip())

        is_english = locale.lower().startswith("en")
        app_name = notch_t("action_name")
        info = {
            "CFBundleDevelopmentRegion": "en" if is_english else "zh_CN",
            "CFBundleExecutable": "ScreenshotEditor",
            "CFBundleIdentifier": f"com.notchany.screenshot-editor.{digest}",
            "CFBundleInfoDictionaryVersion": "6.0",
            "CFBundleName": app_name,
            "CFBundleDisplayName": app_name,
            "CFBundlePackageType": "APPL",
            "CFBundleShortVersionString": "1.0",
            "LSMinimumSystemVersion": "13.0",
            "NSHighResolutionCapable": True,
        }
        contents.mkdir(parents=True, exist_ok=True)
        with (contents / "Info.plist").open("wb") as handle:
            plistlib.dump(info, handle)
    return executable


cache_dir = pathlib.Path.home() / "Library" / "Caches" / "NotchAnyScreenshotEditor"
cache_dir.mkdir(parents=True, exist_ok=True)
locale = os.environ.get("NOTCH_LOCALE", "zh-Hans")

input_paths = [item.strip() for item in os.environ.get("NOTCH_FILES", "").splitlines() if item.strip()]
if not input_paths and os.environ.get("NOTCH_FILE", "").strip():
    input_paths = [os.environ["NOTCH_FILE"].strip()]

captured = False
if input_paths:
    source_path = pathlib.Path(input_paths[0]).expanduser().resolve()
else:
    source_path = cache_dir / f"capture-{uuid.uuid4().hex}.png"
    if not capture_interactive(source_path):
        raise SystemExit(notch_t("capture_cancelled"))
    captured = True

if not source_path.is_file():
    raise SystemExit(notch_t("image_not_found"))

sticker_data = base64.b64decode(STICKER_SHEET_BASE64)
sticker_path = cache_dir / "annotation-stickers-v2.png"
write_if_changed(sticker_path, sticker_data)

try:
    executable = build_native_editor(cache_dir, sticker_data, locale)
except (OSError, subprocess.TimeoutExpired, RuntimeError) as error:
    raise SystemExit(str(error))

log_path = cache_dir / "last-run.log"
with log_path.open("wb") as log_handle:
    process = subprocess.Popen(
        [str(executable), str(source_path), str(sticker_path)],
        stdin=subprocess.DEVNULL,
        stdout=log_handle,
        stderr=subprocess.STDOUT,
    )

time.sleep(0.7)
if process.poll() is not None:
    details = log_path.read_text(encoding="utf-8", errors="replace").strip()
    raise SystemExit(details or notch_t("native_launch_failed"))

if captured:
    cutoff = time.time() - 2 * 24 * 60 * 60
    for old_capture in cache_dir.glob("capture-*.png"):
        try:
            if old_capture != source_path and old_capture.stat().st_mtime < cutoff:
                old_capture.unlink()
        except OSError:
            pass

notch_result(
    summary=notch_t("opened_summary"),
    details=notch_t("opened_details"),
)
